MISSING = object()
_cache = {42: None}


def get_user(user_id, refresh=False):
    if refresh or user_id not in _cache:
        _cache[user_id] = fetch_user(user_id)
    return _cache[user_id]


def fetch_user(user_id):
    return {"id": user_id}

files.tests/test_cache.py:
from src.cache import get_user


def test_cached_none_is_returned_without_refresh():
    assert get_user(42) is None


def test_refresh_fetches_value():
    assert get_user(42, refresh=True) == {"id": 42}
